IMG = ''
# Kaggle job (free GPU): photo → 3D model with Microsoft TRELLIS.2-4B (code MIT, weights MIT).
# Same shape as gpu/kaggle_trellis/ (v1): build an own Python/torch, build the CUDA add-ons, run, write GLBs.
#
# LICENCE NOTE (AGENTS.md rule 6). TRELLIS.2's code and the TRELLIS.2-4B weights are both MIT, but two of the
# dependencies its README installs are NOT commercially safe: nvdiffrast and nvdiffrec are under NVIDIA's
# Source Code License, which is research/non-commercial. They are only used to RENDER previews and for the
# `texturing` pipeline. The shape+texture pipeline and the GLB export (o_voxel.postprocess.to_glb) do not
# import them, so this job installs NEITHER and writes no preview video: the clay renders are done in Blender
# afterwards. Do not add --nvdiffrast/--nvdiffrec here.
#
# T4 NOTE: a T4 is Turing (sm_75): no native bf16 and no flash-attn (needs sm_80+), so ATTN_BACKEND=xformers
# and the weights are loaded in fp16. FlexGEMM/CuMesh are built for sm_75 via TORCH_CUDA_ARCH_LIST=7.5.
import base64, glob, os, subprocess, time
t0 = time.time()


def sh(c, show=1500):
    print('$', c[:200], flush=True)
    r = subprocess.run(c, shell=True, capture_output=True, text=True, executable='/bin/bash')
    print((r.stdout + r.stderr)[-show:], flush=True)
    return r.returncode


os.chdir('/kaggle/working')
open('origami.jpg', 'wb').write(base64.b64decode(IMG))
sh('nvidia-smi; free -g | head -2')
sh('pip install -q uv && uv python install 3.10 && uv venv -p 3.10 /kaggle/tmp/py310')
PY = '/kaggle/tmp/py310/bin/python'
UV = f'uv pip install --python {PY}'
sh(f'{UV} -q torch==2.6.0 torchvision==0.21.0 --index-url https://download.pytorch.org/whl/cu124')
sh(f'{UV} -q pip setuptools wheel ninja "numpy<2" pillow imageio imageio-ffmpeg tqdm easydict opencv-python-headless '
   'trimesh transformers tensorboard pandas zstandard kornia timm scipy safetensors "huggingface_hub>=0.26"')
sh(f'{UV} -q git+https://github.com/EasternJournalist/utils3d.git@9a4eb15e4021b67b12c460c7057d642626897ec8')
sh(f'{UV} -q xformers==0.0.29.post2 --index-url https://download.pytorch.org/whl/cu124')
sh('git clone -b main -q --recursive https://github.com/microsoft/TRELLIS.2.git /kaggle/working/TRELLIS2')

# a CUDA 12.x toolkit for the add-on builds (Kaggle's own nvcc is too new for torch 2.6/cu124)
sh('ls -d /usr/local/cuda*; nvcc --version | tail -2')
c12 = sorted(glob.glob('/usr/local/cuda-12*'))
if c12:
    CUDA = c12[-1]
else:
    CUDA = '/kaggle/tmp/cuda124'
    sh('cd /kaggle/tmp && curl -Ls https://micro.mamba.pm/api/micromamba/linux-64/latest | tar -xj bin/micromamba && '
       f'./bin/micromamba create -y -q -p {CUDA} -c conda-forge -c nvidia/label/cuda-12.4.0 cuda-nvcc=12.4 '
       'cuda-cudart-dev=12.4 cuda-cccl=12.4 libcublas-dev=12.4 libcusparse-dev=12.4 libcusolver-dev libcurand-dev '
       f'cuda-nvrtc-dev=12.4 cuda-profiler-api=12.4 "gxx_linux-64<13" && {CUDA}/bin/nvcc --version | tail -1', show=3000)
    sh(f'[ -d {CUDA}/lib64 ] || ln -s {CUDA}/lib {CUDA}/lib64')
    sh(f'T={CUDA}/targets/x86_64-linux; [ -d $T/include ] && cp -rsn $T/include/* {CUDA}/include/ 2>/dev/null; '
       f'[ -d $T/lib ] && cp -rsn $T/lib/* {CUDA}/lib/ 2>/dev/null; ls {CUDA}/include/cuda_runtime_api.h')
    os.environ['CXX'] = sorted(glob.glob(f'{CUDA}/bin/*-g++') or ['g++'])[0]
print('CUDA toolkit for builds:', CUDA, flush=True)
CXX = os.environ.get('CXX', 'g++')
env = (f'export CXX={CXX} CC={CXX.replace("g++", "gcc")} TORCH_CUDA_ARCH_LIST=7.5 CUDA_HOME={CUDA} '
       f'PATH={CUDA}/bin:/kaggle/tmp/py310/bin:$PATH LD_LIBRARY_PATH={CUDA}/lib64:$LD_LIBRARY_PATH; ')

sh('mkdir -p /kaggle/tmp/ext && cd /kaggle/tmp/ext && '
   'git clone -q --recursive https://github.com/JeffreyXiang/CuMesh.git && '
   'git clone -q --recursive https://github.com/JeffreyXiang/FlexGEMM.git && '
   'cp -r /kaggle/working/TRELLIS2/o-voxel ./o-voxel')
sh(env + f'{PY} -m pip -q install "setuptools<70" wheel ninja packaging; nvcc --version | tail -2; '
   f'{CXX} --version | head -1; {PY} -c "import torch;print(torch.version.cuda, torch.__version__)"', show=1500)
for e in ['FlexGEMM', 'CuMesh', 'o-voxel']:
    # keep the WHOLE build log: the first run filtered it and lost the actual compiler diagnostic
    sh(env + f'cd /kaggle/tmp/ext && {PY} -m pip install -v --no-build-isolation ./{e} '
       f'> /kaggle/working/build_{e}.log 2>&1; echo "exit $?"; tail -60 /kaggle/working/build_{e}.log', show=6000)
for m in ['torch', 'xformers', 'flexgemm', 'cumesh', 'o_voxel', 'utils3d']:
    sh(f'{PY} -c "import {m}; print({m}.__name__, getattr({m}, \'__version__\', \'\'))" || echo MISSING {m}', show=400)
print('install done in', int(time.time() - t0), 's', flush=True)

gen = r"""
import os, sys, time, traceback
os.environ['ATTN_BACKEND'] = 'xformers'
os.environ['SPCONV_ALGO'] = 'native'
os.environ['PYTORCH_CUDA_ALLOC_CONF'] = 'expandable_segments:True'
sys.path.insert(0, '/kaggle/working/TRELLIS2')
import torch
from PIL import Image
from trellis2.pipelines import Trellis2ImageTo3DPipeline
import o_voxel
print('torch', torch.__version__, torch.cuda.get_device_name(0),
      'bf16 supported:', torch.cuda.is_bf16_supported(), flush=True)
pipe = Trellis2ImageTo3DPipeline.from_pretrained('microsoft/TRELLIS.2-4B')
pipe.cuda()
img = Image.open('/kaggle/working/origami.jpg')
for seed in (7, 21):
    t = time.time()
    try:
        mesh = pipe.run(img, seed=seed)[0]
        print('seed', seed, 'verts', len(mesh.vertices), 'faces', len(mesh.faces), flush=True)
        glb = o_voxel.postprocess.to_glb(
            vertices=mesh.vertices, faces=mesh.faces, attr_volume=mesh.attrs, coords=mesh.coords,
            attr_layout=mesh.layout, voxel_size=mesh.voxel_size,
            aabb=[[-0.5, -0.5, -0.5], [0.5, 0.5, 0.5]],
            decimation_target=300000, texture_size=2048, remesh=True, remesh_band=1, remesh_project=0,
            verbose=True)
        glb.export(f'/kaggle/working/origami_samurai_t2_s{seed}.glb', extension_webp=True)
        print('DONE seed', seed, int(time.time() - t), 's', flush=True)
    except Exception:
        traceback.print_exc()
        print('FAILED seed', seed, int(time.time() - t), 's', flush=True)
    print(torch.cuda.memory_summary(abbreviated=True), flush=True)
"""
open('/kaggle/tmp/gen.py', 'w').write(gen)
sh(env + f'{PY} /kaggle/tmp/gen.py', show=8000)
sh('rm -rf /kaggle/working/TRELLIS2 /kaggle/working/origami.jpg; ls -la /kaggle/working')
print('ALL_DONE', int(time.time() - t0), 's')
